func:
if (msg.payload.active === true) {
    msg.payload =
        '<span style="color:#c62828;font-weight:700;">FAULT ACTIVE</span>';
} else {
    msg.payload =
        '<span style="color:#2e7d32;font-weight:700;">OK</span>';
}

return msg;

let p = msg.payload;

// Output 1: IP address
let ipMsg = {
    payload: p.ip
};

// Output 2: Wi-Fi RSSI
let rssiMsg = {
    payload: p.rssi_dbm + " dBm"
};

// Output 3: Uptime
let totalSeconds = Math.floor(p.uptime_ms / 1000);

let hours = Math.floor(totalSeconds / 3600);
let minutes = Math.floor((totalSeconds % 3600) / 60);
let seconds = totalSeconds % 60;

let uptime =
    String(hours).padStart(2, "0") + ":" +
    String(minutes).padStart(2, "0") + ":" +
    String(seconds).padStart(2, "0");

let uptimeMsg = {
    payload: uptime
};

return [
    ipMsg,
    rssiMsg,
    uptimeMsg
];

let p = msg.payload;

function green(text) {
    return {
        payload:
            '<span style="color:#2e7d32;font-weight:700;">' +
            text +
            '</span>'
    };
}

function red(text) {
    return {
        payload:
            '<span style="color:#c62828;font-weight:700;">' +
            text +
            '</span>'
    };
}

function amber(text) {
    return {
        payload:
            '<span style="color:#f9a825;font-weight:700;">' +
            text +
            '</span>'
    };
}

// Overall status
let resultText = String(p.result)
    .replaceAll("_", " ")
    .toUpperCase();

let resultMsg =
    p.result === "ok"
        ? green(resultText)
        : red(resultText);

// Thermal shutdown
let tefMsg =
    p.tef
        ? red("ACTIVE")
        : green("OK");

// Pre-thermal warning
let ptwMsg =
    p.ptw
        ? amber("ACTIVE")
        : green("OK");

// IREF short
let isfMsg =
    p.isf
        ? red("ACTIVE")
        : green("OK");

// IREF open
let iofMsg =
    p.iof
        ? red("ACTIVE")
        : green("OK");

return [
    resultMsg,
    tefMsg,
    ptwMsg,
    iofMsg,
    isfMsg
];

let p = msg.payload;

let pass =
    String(p.result).toLowerCase() === "pass";

let resultText =
    String(p.result).toUpperCase();

let resultMsg = {
    payload:
        '<span style="color:' +
        (pass ? "#2e7d32" : "#c62828") +
        ';font-weight:700;">' +
        resultText +
        '</span>'
};

let affected =
    (p.outputs && p.outputs.length > 0)
        ? p.outputs.join(", ")
        : "NONE";

let outputsMsg = {
    payload:
        '<span style="color:' +
        (affected === "NONE" ? "#2e7d32" : "#c62828") +
        ';font-weight:700;">' +
        affected +
        '</span>'
};

return [
    resultMsg,
    outputsMsg
];

let result =
    String(msg.payload.result).toUpperCase();

let pass = result === "PASS";

msg.payload =
    '<span style="color:' +
    (pass ? "#2e7d32" : "#c62828") +
    ';font-weight:700;">' +
    result +
    '</span>';

return msg;

let result =
    String(msg.payload.result).toUpperCase();

let pass = result === "PASS";

msg.payload =
    '<span style="color:' +
    (pass ? "#2e7d32" : "#c62828") +
    ';font-weight:700;">' +
    result +
    '</span>';

return msg;

let result =
    String(msg.payload.result)
        .replaceAll("_", " ")
        .toUpperCase();

let cleared = result === "CLEARED";

msg.payload =
    '<span style="color:' +
    (cleared ? "#2e7d32" : "#c62828") +
    ';font-weight:700;">' +
    result +
    '</span>';

return msg;

let online =
    String(msg.payload).toLowerCase() === "online";

if (online) {
    msg.payload =
        '<span style="color:#2e7d32;font-weight:700;">ONLINE</span>';
} else {
    msg.payload =
        '<span style="color:#c62828;font-weight:700;">OFFLINE</span>';
}

return msg;

let incoming = msg.payload.channels || {};

let names = [
    "R0","G0","B0",
    "R1","G1","B1",
    "R2","G2","B2",
    "R3","G3","B3",
    "R4","G4","B4",
    "R5","G5","B5",
    "R6","G6","B6",
    "R7","G7","B7"
];

let result = {};

for (let name of names) {
    result[name] = incoming[name] || "nc";
}

msg.payload = result;

return msg;

let channel = String(msg.payload);
flow.set("selectedChannel", channel);

let states = flow.get("channelStates");

if (!states) {
    states = {};

    let connected = [
        "R0","G0","B0",
        "R1","G1","B1",
        "R2","G2","B2"
    ];

    let all = [
        "R0","G0","B0",
        "R1","G1","B1",
        "R2","G2","B2",
        "R3","G3","B3",
        "R4","G4","B4",
        "R5","G5","B5",
        "R6","G6","B6",
        "R7","G7","B7"
    ];

    for (let ch of all) {
        states[ch] = {
            enabled: connected.includes(ch),
            gs: 4095,
            dc: 127
        };
    }

    flow.set("channelStates", states);
}

let state = states[channel];

return [
    { payload: Boolean(state.enabled) },
    { payload: Number(state.gs) },
    { payload: Number(state.dc) }
];

let channel = flow.get("selectedChannel") || "R0";

let gs = Math.round(Number(msg.payload));
gs = Math.max(0, Math.min(4095, gs));

flow.set("selectedGS", gs);

msg.payload = "gs:" + channel + ":" + gs;

return msg;

let channel = flow.get("selectedChannel") || "R0";

let dc = Math.round(Number(msg.payload));
dc = Math.max(0, Math.min(127, dc));

msg.payload = "dc:" + channel + ":" + dc;

return msg;

let channel = flow.get("selectedChannel") || "R0";

let enabled = Number(msg.payload) ? 1 : 0;

let states = flow.get("channelStates") || {};

if (!states[channel]) {
    states[channel] = {
        enabled: true,
        gs: 4095,
        dc: 127
    };
}

states[channel].enabled = Boolean(enabled);

flow.set("channelStates", states);

msg.payload =
    "enable:" + channel + ":" + enabled;

return msg;

if (msg.topic !== "tlc6c5724/device01/channel-control") {
    return null;
}

let p = msg.payload;

// Just in case MQTT gives us a JSON string
if (typeof p === "string") {
    try {
        p = JSON.parse(p);
    } catch (e) {
        return null;
    }
}

let selected =
    flow.get("selectedChannel") || "R0";

// Store actual state reported by ESP32
let states =
    flow.get("channelStates") || {};

if (!states[p.channel]) {
    states[p.channel] = {
        enabled: true,
        gs: 4095,
        dc: 127
    };
}

states[p.channel].enabled =
    Boolean(p.enabled);

states[p.channel].gs = Number(p.gs);
states[p.channel].dc = Number(p.dc);

flow.set("channelStates", states);

// Only update the switch if this is
// the channel currently selected on screen
if (p.channel !== selected) {
    return null;
}

if (p.channel !== selected) {
    return null;
}

return [
    { payload: Boolean(p.enabled) },
    { payload: Number(p.gs) },
    { payload: Number(p.dc) }
];

if (msg.topic !== "tlc6c5724/device01/automatic-test") {
    return null;
}

let p = msg.payload;

// Handle either parsed JSON or a JSON string.
if (typeof p === "string") {
    try {
        p = JSON.parse(p);
    } catch (e) {
        return null;
    }
}

const labels = {
    rgb_cycle: "RGB COLOUR CYCLE",
    rgb_phase_rotation: "RGB PHASE ROTATION",
    led_chase: "RGB SEQUENTIAL CHASE",
    brightness_sweep: "BRIGHTNESS SWEEP",
    all_white: "ALL WHITE",
    all_off: "ALL OFF",
    none: "NONE"
};

const running =
    String(p.state || "").toLowerCase() === "running";

const testName =
    labels[p.test] ||
    String(p.test || "none")
        .replaceAll("_", " ")
        .toUpperCase();

let modeMsg = {
    payload: running
        ? '<span style="color:#1565c0;font-weight:700;">' +
          testName +
          '</span>'
        : '<span style="color:#616161;font-weight:700;">IDLE</span>'
};

let stateMsg = {
    payload: running
        ? '<span style="color:#2e7d32;font-weight:700;">RUNNING</span>'
        : '<span style="color:#616161;font-weight:700;">STOPPED</span>'
};

return [modeMsg, stateMsg];
